const ARTICLES = [
  {id:1, cat:"uls-tor", title:"Монгол Улс Малайзад Алтантуяагийн хэргээр дипломат эсэргүүцэл илэрхийлж, шударга шүүхээр шийдвэрлэхийг шаардав", titleEn:"Mongolia lodges diplomatic protest with Malaysia over Altantuya case, demanding a fair resolution", time:"15 мин", timeEn:"15 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Kuala%20Lumpur%20Malaysia%20Skyline-01.jpg?width=1000", text:"Монгол Улс Малайзын Засгийн газарт 2006 онд амь насаа алдсан иргэн Ш.Алтантуяагийн хэргийн талаар дипломат эсэргүүцэл илэрхийлсэн тухай Монгол Улсын тусгай элч Г.Занданшатар арваннэгдүгээр сарын 12-нд мэдэгдлээ. 28 настай Алтантуяа Шаарийбуу 2006 оны аравдугаар сард Куала-Лумпурын ойролцоо буудуулж амиа алдаж, цогцсыг нь цэргийн зориулалттай тэсрэх бодисоор устгасан билээ. Энэхүү хэрэг гарснаас хойш бараг 20 жил өнгөрсөн ч шударга ёс бүрэн тогтоогдоогүй байгаа нь Монголын талын эсэргүүцлийг хүргэсэн байна.\n\nМонголын тал Малайзын эрх баригчдад дөрвөн үндсэн шаардлага тавьсан байна. Үүнд ар гэрийнхний гаргасан хуулийн маргааныг шударгаар хэлэлцэх, шинээр гарч болзошгүй нотлох баримтыг шалгах, хэргийн явцын талаар тогтмол мэдээлэх, мөн хэрэгт холбогдон ял сонссон цагдаагийн хуучин ажилтан Сирул Азхар Умарын мэдүүлгийг авах зэрэг багтжээ. Сирул өдгөө Австралид байгаа бөгөөд түүний хамтран зүтгэгч Азилах Хадригийн хамт Алтантуяаг хөнөөсөн хэрэгт буруутгагдан ял сонссон юм.\n\nЭнэ оны нэгдүгээр сард Малайзын Давж заалдах шүүх иргэний хэргийн хүрээнд Засгийн газрын хариуцлагыг хүчингүй болгож, ар гэрт олгох нөхөн төлбөрийг 5 сая ринггитээс 1.4 сая ринггит орчим болгон бууруулсан нь Монголын талын бухимдлыг улам нэмэгдүүлсэн байна. Үүнтэй холбогдуулан Монгол Улс “Dignity for Altantuya” буюу “Алтантуяагийн нэр төрийн төлөө” нэртэй олон улсын өргөдөл санаачилж, хууль ёсны хариуцлага тооцох, Малайз, Австралийн хамтын ажиллагааг нэмэгдүүлэхийг уриалжээ.\n\nМонголын тал хэнд ч цаазаар авах ял оноохыг шаардахгүй гэдгээ тодорхой хэлсэн бөгөөд зөвхөн Сирулын мэдүүлгийг авч, цаазын ялаас хамгаалах баталгаатайгаар үнэнийг тогтоохыг хүсч байна. Арваннэгдүгээр сарын 12-нд зарласан энэхүү эсэргүүцэл нь 20 орчим жил үргэлжилж буй хэргийг шударгаар шийдвэрлэхэд чиглэсэн дипломат алхам боллоо.", textEn:"Mongolia has lodged a diplomatic protest with the Government of Malaysia over the case of its citizen Sh. Altantuya, who was killed in 2006, Special Envoy G. Zandanshatar announced on November 12. Altantuya Shaariibuu, aged 28, was shot dead near Kuala Lumpur in October 2006 and her body was destroyed with military-grade explosives. Almost 20 years have passed since the killing, yet justice has still not been fully served, prompting Mongolia's protest.\n\nThe Mongolian side has presented four main demands to the Malaysian authorities. They include a fair hearing of the family's legal challenge, examination of any newly emerging evidence, regular updates on the proceedings, and securing the testimony of former police officer Sirul Azhar Umar, who was convicted in the case. Sirul is now in Australia; he and his colleague Azilah Hadri were convicted of murdering Altantuya.\n\nIn January this year, Malaysia's Court of Appeal removed the government's liability in the civil case and cut the compensation awarded to the family from 5 million ringgit to around 1.4 million ringgit, deepening Mongolia's frustration. In response, Mongolia has launched an international petition called \"Dignity for Altantuya\", urging lawful accountability and greater cooperation between Malaysia and Australia.\n\nMongolia has made clear that it does not seek the death penalty for anyone, but wants Sirul's testimony secured with guarantees against execution so that the truth can be established. The protest announced on November 12 is a diplomatic step aimed at bringing a fair resolution to a case that has lasted nearly two decades."},
  {id:2, cat:"edi-zasag", title:"Ерөнхий сайд Н.Учрал: 1072 хувьцааг үржүүлж, өвлүүлж, арилжих эрх бодитоор нээх ажил үргэлжилж байна", titleEn:"PM N. Uchral: Work continues to genuinely open the right to multiply, inherit and trade the 1,072 shares", time:"30 мин", timeEn:"30 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Sharyn%20Gol%20Coal%20Mine.jpg?width=760", text:"Монгол Улсын Ерөнхий сайд Н.Учрал болон Улсын Их Хурал, Засгийн газрын гишүүд Өмнөговь аймаг дахь “Эрдэнэс Тавантолгой” ХК-ийн уурхайд ажиллаж, төслийн бүтээн байгуулалт, санхүү, эдийн засгийн үзүүлэлтүүдтэй танилцан, уурхайчидтай уулзалт хийлээ. Уулзалтын үеэр Ерөнхий сайд иргэдийн эзэмшиж буй 1072 хувьцааг үржүүлж, өвлүүлж, бэлэглэх, арилжиж, худалдах эрхийг бодитоор нээх ажил үргэлжилж байгааг онцолсон байна.\n\n“Эрдэнэс Тавантолгой” ХК-ийн гүйцэтгэх захирал Б.Чагнаадоржийн мэдээлснээр компани 2010 онд байгуулагдсанаас хойш нийт 210 сая тонн нүүрс олборлоод байна. 2026 оны эхний есөн сарын байдлаар 28.6 сая тонн нүүрс олборлосон нь өмнөх оны мөн үеэс 30 хувиар өссөн үзүүлэлт юм. Борлуулалт 29 сая тоннд хүрч 48-50 хувиар нэмэгдэж, борлуулалтын орлого 2 тэрбум ам.долларыг давж, төлөвлөгөөг 126 хувиар биелүүлжээ. Компанийн цэвэр ашиг 1.5 их наяд төгрөгт хүрч, жилийн төлөвлөгөөг есөн сарын байдлаар 48 хувиар давуулан биелүүлсэн байна.\n\nТайлант хугацаанд улс, орон нутгийн төсөвт 1.4 их наяд төгрөгийн татвар, төлбөр, хураамж төлж, төлөвлөгөөгөө 33 хувиар давуулсан байна. Үүнээс гадна “Чингис хаан” Үндэсний баялгийн санд энэ ондоо багтаан 675 тэрбум төгрөгийг төвлөрүүлэхээр ажиллаж байна. 2026 оны долоодугаар сарын 1-нээс өртөг зардал бууруулах хөтөлбөрийг хэрэгжүүлснээр 604 тэрбум төгрөгийн зардлыг хэмнэж, нэг тонн нүүрсний өртгийг 6 ам.доллароор бууруулсан байна.\n\nЗасаглалын шинэчлэлийн хүрээнд ирэх нэгдүгээр сарын 1-нээс Төрийн болон орон нутгийн өмчийн тухай шинэ хууль хэрэгжиж эхэлнэ. Мөн ирэх оны долоодугаар сараас эхлэн шаардлагатай инженер, операторуудын ажлын байрыг их, дээд сургуулиудын төгсөгчдөд нээлттэй зарлаж, сурлагын голчоор нь шалгаруулан шууд ажлын байраар хангадаг болно. Ерөнхий сайд уурхайчдад талархал илэрхийлж, тэдний хөдөлмөрийн үрээр 11 дүгээр сарын 1-нээс 413 мянган ахмад настан шинээр суурь тэтгэвэр авч эхэлж, олон мянган эмч, багш, төрийн үйлчилгээний албан хаагчдын цалин 50 хувиар нэмэгдсэнийг онцолсон байна.", textEn:"Prime Minister N. Uchral, together with members of the State Great Khural and the Government, visited the \"Erdenes Tavantolgoi\" JSC mine in Umnugovi aimag, reviewed the project's construction, financial and economic indicators, and met with miners. During the visit, the Prime Minister stressed that work continues to genuinely open citizens' right to multiply, inherit, gift, trade and sell their 1,072 shares.\n\nAccording to CEO B. Chagnaadorj, the company has mined a total of 210 million tonnes of coal since its founding in 2010. In the first nine months of 2026, it mined 28.6 million tonnes, up 30 percent year on year. Sales reached 29 million tonnes, up 48-50 percent, sales revenue exceeded 2 billion US dollars, fulfilling the plan by 126 percent. Net profit reached 1.5 trillion tugriks, exceeding the annual plan by 48 percent in nine months.\n\nDuring the reporting period, the company paid 1.4 trillion tugriks in taxes, fees and charges to the state and local budgets, exceeding its plan by 33 percent. It is also working to channel 675 billion tugriks into the \"Chinggis Khaan\" National Wealth Fund within this year. A cost-reduction programme launched on July 1, 2026 saved 604 billion tugriks and cut the cost per tonne of coal by 6 US dollars.\n\nAs part of governance reform, a new Law on State and Local Property will take effect from January 1 next year. From July next year, jobs for engineers and operators will be openly advertised to university graduates, who will be selected by grade point average and hired directly. The Prime Minister thanked the miners, noting that their work made it possible for 413,000 pensioners to start receiving the new basic pension from November 1, and for thousands of doctors, teachers and public servants to receive a 50 percent pay rise."},
  {id:3, cat:"niigem", title:"Их цас, цасан шуурга: өнөөдөр баруун аймгуудаар цас орж, хүйтэрнэ", titleEn:"Heavy snow and blizzards: snow expected across western aimags today as temperatures drop", time:"45 мин", timeEn:"45 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Blizzard%20of%20January%201999.jpg?width=760", text:"Цаг уур, орчны шинжилгээний газраас малчид, иргэд, тээвэрчдэд зориулан сэрэмжлүүлэг гаргажээ. Өнөөдөр буюу арваннэгдүгээр сарын 15-нд Увс, Ховд, Завхан, Архангайн зарим, Говь-Алтай, Баянхонгор, Өвөрхангайн ихэнх, Өмнөговь, Дундговийн баруун сумдын нутгаар 0.0-4.0 мм цас орж, цасан шуурга шуурна. Өнгөрсөн шөнө Баян-Өлгий, Увс, Ховд, Завханы зарим, Говь-Алтай, Баянхонгорын ихэнх сумдын нутгаар мөн цас орсон байна.\n\nИрэх өдрүүдэд цас үргэлжлэн орох төлөвтэй байна. Арваннэгдүгээр сарын 15-16-нд шилжих шөнө Завхан, Говь-Алтай, Баянхонгор, Өвөрхангайн ихэнх, Архангай, Төв, Булган, Сэлэнгийн зарим, Хөвсгөлийн өмнөд, Өмнөговь, Дундговийн баруун сумдын нутгаар, 16-ны өдөр Завхан, Хөвсгөлийн зүүн, Говь-Алтай, Баянхонгор, Дундговийн хойд, Архангай, Өвөрхангай, Булган, Сэлэнгэ, Төв, Хэнтийн ихэнх сумдын нутгаар цас орж, цасан шуурга шуурна. 17-нд Төв, Сэлэнгэ, Өмнөговь, Дундговь, Дорноговийн зарим, Хэнтий, Дорнод, Сүхбаатарын ихэнх сумдын нутгаар 0.0-6.0 мм цас орох төлөвтэй байна.\n\nСалхи 15-нд Алтайн уулархаг нутгаар, 16-нд нутгийн зарим газраар, 17-нд говь, тал, хээрийн нутгаар, 18-нд тал, хээрийн нутгаар секундэд 15-17 метр хүрч ширүүснэ. Ихэнх нутгаар хүйтэрч, шөнөдөө Дархадын хотгор, Завхан, Заг, Байдраг голын эхээр 25-30 хэм, Алтай, Хангай, Хөвсгөл, Хэнтийн уулархаг нутаг, Идэр, Тэс, Туул, Тэрэлж голын хөндийгөөр 19-24 хэм, говийн бүс нутгийн өмнөд хэсгээр 6-11 хэм, бусад нутгаар 12-17 хэм хүйтэн байна. Өдөртөө уулархаг нутгаар 10-15 хэм хүйтэн, говийн өмнөд хэсгээр 3 хэмийн хүйтнээс 2 хэмийн дулаан, бусад нутгаар 4-9 хэм хүйтэн байх төлөвтэй байна.\n\nМалчид, иргэд, тээвэрчид зам, даваа, гүвээнд үзэгдэх орчин хязгаарлагдаж, халтиргаа гулгаа, мөстөлт үүсэхийг анхаарч, хол замд гарахдаа бэлтгэлтэй байхыг цаг уурын байгууллагаас анхааруулж байна.", textEn:"The National Agency for Meteorology and Environmental Monitoring has issued a warning for herders, residents and drivers. Today, November 15, snow of 0.0-4.0 mm and blizzards are expected in parts of Uvs, Khovd, Zavkhan and Arkhangai, most of Govi-Altai, Bayankhongor and Uvurkhangai, and western soums of Umnugovi and Dundgovi. Snow also fell overnight in parts of Bayan-Ulgii, Uvs, Khovd and Zavkhan and most of Govi-Altai and Bayankhongor.\n\nSnow is forecast to continue in the coming days. On the night of November 15-16, snow is expected in most of Zavkhan, Govi-Altai, Bayankhongor and Uvurkhangai, parts of Arkhangai, Tuv, Bulgan and Selenge, southern Khuvsgul, and western Umnugovi and Dundgovi. On November 16, snow and blizzards will cover most of Zavkhan, eastern Khuvsgul, Govi-Altai, Bayankhongor, northern Dundgovi, Arkhangai, Uvurkhangai, Bulgan, Selenge, Tuv and Khentii. On November 17, 0.0-6.0 mm of snow is expected in parts of Tuv, Selenge, Umnugovi, Dundgovi and Dornogovi and most of Khentii, Dornod and Sukhbaatar.\n\nWinds will strengthen to 15-17 metres per second in the Altai mountains on the 15th, in parts of the country on the 16th, and across the Gobi, steppe and field regions on the 17th and 18th. Temperatures will fall across most of the country: at night, minus 25-30 degrees in the Darkhad Depression and the headwaters of the Zavkhan, Zag and Baidrag rivers, minus 19-24 degrees in the Altai, Khangai, Khuvsgul and Khentii mountains and the valleys of the Ider, Tes, Tuul and Terelj rivers, minus 6-11 degrees in the southern Gobi, and minus 12-17 degrees elsewhere. Daytime temperatures will be minus 10-15 degrees in the mountains, from minus 3 to plus 2 degrees in the southern Gobi, and minus 4-9 degrees elsewhere.\n\nHerders, residents and drivers are warned that visibility will be limited on roads, passes and hills, with slippery conditions and icing, and are advised to prepare carefully before long journeys."},
  {id:4, cat:"niigem", title:"Орон сууцны захиалгын гэрээнээс хохирсон иргэдийн 870 гаруй гомдлыг шалгаж байна", titleEn:"More than 870 complaints from victims of housing pre-sale contracts under review", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Ulaanbaatar%20new%20buildings%20in%20Yaarmag.jpg?width=760", text:"Улсын Их Хурлын Өргөдлийн байнгын хороо арваннэгдүгээр сарын 12-нд хуралдаж, тус байнгын хорооноос Засгийн газар, яам, агентлагт шийдвэрлүүлэхээр илгээсэн иргэд, хуулийн этгээдийн өргөдөл, гомдлыг хэрхэн шийдвэрлэсэн тухай мэдээллийг сонсон хэлэлцлээ. 2025 оны есдүгээр сарын 10-наас 2026 оны аравдугаар сарын 13-ны хугацаанд ирүүлсэн иргэд, хуулийн этгээдийн нийт 73 өргөдөл, гомдлыг Засгийн газрын 18 байгууллага, албан тушаалтанд шилжүүлсний хариуг Засгийн газраас илтгэсэн байна.\n\nИргэдээс ирүүлсэн өргөдөл, гомдлын 24.7 хувийг шийдвэрлэсэн, 65.8 хувь нь шийдвэрлэх шатанд байгааг Монгол Улсын сайд, Засгийн газрын Хэрэг эрхлэх газрын дарга Б.Энхбаяр танилцууллаа. Иргэдээс ирүүлсэн өргөдөл, гомдлын дийлэнх хувийг орон сууцтай холбоотой асуудал эзэлж байгаа тул Монгол Улсын Ерөнхий сайдын 2026 оны 154 дүгээр захирамжаар Хууль зүй, дотоод хэргийн сайдаар ахлуулсан ажлын хэсэг байгуулан ажиллаж эхэлсэн байна.\n\nОрон сууцны захиалгын гэрээний улмаас хохирсон иргэдийн хууль ёсны эрх ашгийг хамгаалах асуудлыг шалгаж шийдвэрлэх үүрэг бүхий тус ажлын хэсэг одоогоор 870 гаруй өргөдөл, гомдлыг хүлээн авч, шалгаж байна. Орон сууцны захиалга, залилан, хохирол барагдуулах болон тэтгэвэр, тэтгэмжийн зөрүү ялгаа, итгэлцүүр тооцооллыг жигдлэх, төрийн байгууллага, албан хаагчийн үйл ажиллагаа, хуулийн зохицуулалт, санхүүгийн дэмжлэг, хэрэг зөрчилтэй холбоотой өргөдлүүдийг хэлэлцсэн байна.\n\nОрон сууцны залилах гэмт хэргээс урьдчилан сэргийлэх арга хэмжээний тухай Засгийн газрын 2026 оны 406 дугаар тогтоолыг баталж, иргэдийг хохирохоос урьдчилан сэргийлэх арга хэмжээг авч байгаа аж. Өргөдлийн байнгын хорооны дарга О.Номинчимэг тэргүүтэй гишүүд энэ өдрийн хуралдаанд оролцож, гомдлыг шийдвэрлэх явцыг хянах болно.", textEn:"The Standing Committee on Petitions of the State Great Khural met on November 12 to hear how petitions and complaints from citizens and legal entities, forwarded to the Government, ministries and agencies for resolution, have been handled. The Government reported on 73 petitions and complaints submitted between September 10, 2025 and October 13, 2026, which were forwarded to 18 government bodies and officials.\n\nB. Enkhbayar, Minister of Mongolia and Head of the Government Secretariat, said that 24.7 percent of the petitions and complaints had been resolved and 65.8 percent were in progress. As most complaints from citizens concern housing, a working group headed by the Minister of Justice and Home Affairs was set up under the Prime Minister's Order No. 154 of 2026 and has begun its work.\n\nThe working group, tasked with examining and resolving issues to protect the lawful rights of citizens harmed by housing pre-sale contracts, has so far received and is reviewing more than 870 petitions and complaints. The committee also discussed petitions on housing orders and fraud, compensation for damages, equalising pension and benefit differences and coefficients, the work of state bodies and officials, legal regulation, financial support, and offences.\n\nThe Government's Resolution No. 406 of 2026 on measures to prevent housing fraud crimes has been adopted to protect citizens from harm. Members of the committee, led by Chair O. Nominchimeg, took part in the session and will monitor how the complaints are resolved."},
  {id:5, cat:"edi-zasag", title:"2027 оны төсөв батлагдлаа: цалингийн татварын хөнгөлөлт, тэтгэврийн нэмэгдэл юу өөрчлөгдөх вэ", titleEn:"2027 budget approved: what changes with the income-tax relief and pension rise", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Mongolian%20parliament%20members.jpg?width=760", text:"Улсын Их Хурал арваннэгдүгээр сарын 13-нд Монгол Улсын 2027 оны төсвийг эцэслэн баталлаа. Батлагдсан төсвөөр орлогыг 39.2 их наяд төгрөг, зарлагыг 41.5 их наяд төгрөгөөр тогтоож, алдагдал 2.3 их наяд төгрөг байхаар тусгасан байна. Улсын Их Хурал Засгийн газрын өргөн барьсан анхны төслөөс орлого, зарлагыг тус бүр 2.1 их наяд төгрөгөөр бууруулсан бөгөөд анхны төсөлд орлого 41.3 их наяд, зарлага 43.6 их наяд төгрөг байхаар тусгагдсан байв.\n\nСанал хураалтад оролцсон 110 гишүүний 82.7 хувь нь төсвийг дэмжсэн байна. Төсөв тав дахь хэлэлцүүлгээрээ батлагдсан бөгөөд хуулиар тогтоосон арваннэгдүгээр сарын 15-ны эцсийн хугацаанаас хоёр хоногийн өмнө батлагдлаа. Улсын Их Хурлын дарга С.Бямбацогт баталсан төсвийг ард түмний гар дээр үлдэх мөнгийг нэмэгдүүлэх төсөв гэж тодорхойлсон байна.\n\nӨрхийн хувьд хамгийн чухал өөрчлөлт нь хувь хүний орлогын албан татварын хөнгөлөлт юм. Сард 792,000 төгрөг хүртэлх цалингаас хувь хүний орлогын албан татвар авахгүй боллоо. Мөн дундаж тэтгэврийг 1.3 сая төгрөг хүртэл нэмэгдүүлэхээр тусгаж, төрийн албан хаагчдын цалинг 2027 оны хоёрдугаар улирлаас эхлэн нэмэгдүүлэхээр төлөвлөжээ.\n\nГэсэн хэдий ч Төрийн аудитын байгууллага төсвийн төслийн аудитаар инфляц болон орлогын тодорхойгүй байдлын талаар анхааруулсан байна. Төрийн аудитын ерөнхий аудитор М.Сандагийн есдүгээр сарын 26-нд танилцуулсан аудитаар анхны төслийн алдагдлыг ДНБ-ий 2.0 хувь гэж тооцсон байв. Батлагдсан төсөв ирэх оноос хэрэгжиж эхлэх бөгөөд иргэдийн амьжиргаанд хэрхэн нөлөөлөх нь ирэх саруудад харагдах болно.", textEn:"The State Great Khural finally approved Mongolia's 2027 budget on November 13. The approved budget sets revenue at 39.2 trillion tugriks and spending at 41.5 trillion tugriks, with a deficit of 2.3 trillion tugriks. Parliament cut both revenue and spending by 2.1 trillion tugriks from the Government's initial draft, which had proposed revenue of 41.3 trillion and spending of 43.6 trillion tugriks.\n\nOf the 110 members who took part in the vote, 82.7 percent supported the budget. It passed at its fifth deliberation, two days before the statutory deadline of November 15. Speaker S. Byambatsogt described the approved budget as one that increases the money remaining in people's hands.\n\nThe most important change for households is the income-tax relief: monthly salaries of up to 792,000 tugriks will be exempt from personal income tax. The average pension is to rise to 1.3 million tugriks, and public-sector salaries are planned to increase from the second quarter of 2027.\n\nHowever, the State Audit Organization warned in its audit of the draft budget about inflation and uncertain revenue. The audit presented by Auditor General M. Sandag on September 26 put the draft deficit at 2.0 percent of GDP. The approved budget takes effect next year, and its impact on people's livelihoods will become clear in the coming months."},
  {id:6, cat:"delhii", title:"Иран Хормузын хоолойд “Талара” танкерийг саатуулж, АНУ хоёр хөлөг онгоцыг зогсоолоо", titleEn:"Iran seizes 'Talara' tanker in Strait of Hormuz as US disables two vessels", time:"30 мин", timeEn:"30 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Oil%20Tanker%20in%20North%20Sea%203928.jpg?width=760", text:"Ираны Исламын хувьсгалын хамгаалалтын корпусын тэнгисийн цэргийн хүчин арваннэгдүгээр сарын 14-ний баасан гарагт Хормузын хоолойгоор дайран өнгөрч байсан “Талара” хэмээх худалдааны танкерийг саатуулсан болохыг Ираны тал баасан гарагт баталгаажууллаа. Маршаллын арлуудад бүртгэлтэй тус хөлөг онгоц Арабын Нэгдсэн Эмират Улсаас Сингапур руу 30,000 тонн нефть химийн бүтээгдэхүүн тээвэрлэж явсан бөгөөд шүүхийн шийдвэрийн дагуу саатуулсан гэж Ираны тал мэдэгдсэн байна.\n\nХувьсгалын хамгаалалтын корпусынхан нисдэг тэргээр хөлөг онгоцонд бууж, түүнийг Ираны усан хил рүү чиглүүлсэн болохыг АНУ-ын Төв командлал мэдээллээ. Хөлгийг удирддаг Кипр дэх “Columbia Shipmanagement” компани баасан гарагийн өглөө хөлөгтэй холбоо тасарсан тухай мэдээлсэн байна. Их Британийн Тэнгисийн худалдааны үйл ажиллагааны төв ч мөн “төрийн үйл ажиллагаа” байж болзошгүй гэж тэмдэглэжээ. Ираны тал уг хөлгийг “хууль бус ачаа” тээвэрлэж байсан гэж мэдэгдсэн ч дэлгэрэнгүй мэдээлэл өгөөгүй байна.\n\nҮүний зэрэгцээ АНУ-ын Төв командлал Ираны далбаатай хоёр танкерийг Ираны боомт руу нэвтрэхийг завдах үед нь зогсоосон тухай мэдээллээ. Мөн баасан гарагт АНУ, Иран хоёр Хормузын хоолойд гал нээсэн нь байлдааны ажиллагааг зогсоох эмзэг түр завсарлага болон байнгын гал зогсоох хэлэлцээнд аюул учруулж болзошгүй гэж үзэж байна. НҮБ-ын мэдээлснээр 2026 оны хоёрдугаар сараас хойш Хормузын хоолой орчимд 25 далайчин амь үрэгдэж, гуравдугаар сарын 1-нээс арваннэгдүгээр сарын 11-нийг хүртэл хөлөг онгоцны аюулгүй байдлын 136 тохиолдол бүртгэгдсэн байна.\n\nХормузын хоолой нь дэлхийн газрын тосны 20 орчим хувь нь дайран өнгөрдөг нарийн усан зам бөгөөд энэ үйл явдал дэлхийн эрчим хүчний зах зээлд санаа зовнил үүсгэж байна. АНУ-ын Тэнгисийн 5-р флот нөхцөл байдлыг ажиглаж байгаа бөгөөд худалдааны хөлөг онгоцууд олон улсын усанд саадгүй зорчих эрхтэй гэдгийг мэдэгдсэн байна.", textEn:"Iran's Islamic Revolutionary Guard Corps navy seized the commercial tanker \"Talara\" as it transited the Strait of Hormuz on Friday, November 14, the Iranian side confirmed on Saturday. The Marshall Islands-flagged vessel was carrying 30,000 tonnes of petrochemical products from the United Arab Emirates to Singapore, and Iran said it was seized under a court order to protect the country's interests.\n\nUS Central Command said Revolutionary Guard forces boarded the tanker by helicopter and steered it into Iranian waters. Columbia Shipmanagement in Cyprus, which manages the vessel, reported on Friday morning that it had lost contact with the crew shortly before the ship disappeared from normal tracking near the UAE coast. The British military's United Kingdom Maritime Trade Operations centre also noted possible \"state activity\" that forced the tanker into Iranian waters. Iran said the vessel was carrying an \"illegal consignment\" but gave no details.\n\nAt the same time, US Central Command said the US military had disabled two Iranian-flagged tankers as they attempted to access Iranian ports in the Gulf of Oman. Hours earlier, the US and Iran traded fire in the Strait of Hormuz, threatening a fragile pause in fighting and efforts to reach a lasting ceasefire. According to the UN, at least 25 seafarers have been killed in and around the Strait of Hormuz since February 2026, and the International Maritime Organization tracked 136 vessel security incidents between March 1 and November 11.\n\nThe Strait of Hormuz is a narrow waterway through which around 20 percent of the world's oil passes, and the incident has raised concern in global energy markets. The US Navy's 5th Fleet said it was monitoring the situation and that commercial vessels are entitled to largely unimpeded navigation in international waters."},
  {id:7, cat:"delhii", title:"COP31: Анталья хотод уур амьсгалын санхүүжилтийн маргаан үргэлжилж байна", titleEn:"COP31: Climate finance dispute continues in Antalya", time:"45 мин", timeEn:"45 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Antalya%20Bight.jpg?width=760", text:"НҮБ-ын Уур амьсгалын өөрчлөлтийн тухай 31 дүгээр бага хурал буюу COP31 Туркийн Анталья хотод арваннэгдүгээр сарын 9-нөөс 20-ныг хүртэл үргэлжилж байна. Ойролцоогоор 200 орны төлөөлөгчид, 100,000 гаруй хүн оролцож байгаа энэ хурал нь уур амьсгалын санхүүжилт, дасан зохицох болон эрчим хүчний шилжилтийг хурдасгах асуудлаар хэлэлцэж байна. Туркийн Байгаль орчны сайд Мурат Курум хурлыг даргалж, Австралийн Уур амьсгалын сайд Крис Боуэн хэлэлцээг удирдаж байгаа нь ер бусын хамтарсан зохион байгуулалт юм.\n\nХурлын нээлтэд НҮБ-ын Ерөнхий нарийн бичгийн дарга Антониу Гутерриш дэлхийн удирдагчдад хандан уур амьсгалын хямралыг шийдвэрлэхэд “ноцтой хандахыг” уриалсан байна. Тэрбээр ялгаруулалтыг хурдан бууруулах, чулуужсан түлшнээс шударга шилжилтийг хурдасгах, эмзэг орнуудад шаардлагатай санхүүжилт, хамгааллыг олгохыг шаарджээ. Хэлэлцээр эхлэхээс өмнөх ням гарагт хөгжиж буй орнууд уур амьсгалын санхүүжилтийг албан ёсны хэлэлцэх асуудлын жагсаалтад оруулахыг шаардсанаар хэлэлцээ удаан үргэлжилж, нээлтийн ёслол нэг цаг хагасаар хойшилсон байна.\n\nАрваннэгдүгээр сарын 11-12-нд болсон Дэлхийн удирдагчдын дээд хэмжээний уулзалтад Туркийн Ерөнхийлөгч Режеп Тайип Эрдоган, НҮБ-ын Ерөнхий нарийн бичгийн дарга Антониу Гутерриш болон олон улсын удирдагчид оролцож, үндэсний мэдэгдэл хийж, уур амьсгалын санхүүжилт, эрчим хүчний дэд бүтэц, хотын тогтвортой байдал, Африкийн цэвэр хоол хийх зэрэг асуудлыг хэлэлцсэн байна. Турк улс дэлхийн эрчим хүчний хэрэгцээний цахилгаан эрчим хүчний эзлэх хувийг өнөөгийн 20 орчим хувиас 2035 он гэхэд 35 хувьд хүргэх сайн дурын “цахилгаанжуулалт” амлалтад нэгдэхийг уриалж байна.\n\nЭнэ хурал нь Парисын хэлэлцээрийн хүрээнд хамтын ахиц дэвшлийг үнэлэх хоёр дахь Дэлхийн нөөцийн тооллогыг эхлүүлэх үйл явдал болж байна. Уур амьсгалын үйл ажиллагааны хяналтын байгууллагын шинэ үнэлгээгээр сүүлийн таван жилд дэлхийн уур амьсгалын үйл ажиллагаа бараг ахиц гаргаагүй байна.", textEn:"The 31st UN Climate Change Conference, COP31, is under way in Antalya, Türkiye, from November 9 to 20. Delegations from nearly 200 countries and more than 100,000 participants are discussing climate finance, adaptation and accelerating the energy transition. Türkiye's Environment Minister Murat Kurum presides over the conference, while Australia's Climate Minister Chris Bowen leads the negotiations in an unusual joint arrangement.\n\nAt the opening, UN Secretary-General António Guterres urged world leaders to \"get serious\" about tackling the climate crisis. He called for faster emissions cuts, an accelerated just transition from fossil fuels, and the finance and protection vulnerable countries need. Talks ran late into the previous Sunday over demands by developing nations to include climate finance on the official agenda, delaying the opening ceremony by an hour and a half.\n\nThe World Leaders' Summit on November 11-12 brought together Turkish President Recep Tayyip Erdoğan, UN Secretary-General António Guterres and other leaders for national statements and discussions on climate finance, energy infrastructure, urban resilience and clean cooking in Africa. Türkiye is inviting countries to join a voluntary \"electrification\" pledge to raise the share of global energy demand met by electricity from around 20 percent today to 35 percent by 2035.\n\nThe conference also marks the launch of the second Global Stocktake, the process under the Paris Agreement to assess collective progress towards its long-term goals. A new assessment by Climate Action Tracker indicates that global climate action has made little progress over the past five years."},
  {id:8, cat:"delhii", title:"Трамп хүнсний импортын татварыг цуцалж, инфляцын эсрэг чиглэлээ өөрчлөв", titleEn:"Trump scraps tariffs on food imports in inflation U-turn", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Donald%20Trump%20swearing%20in%20ceremony.jpg?width=760", text:"АНУ-ын Ерөнхийлөгч Дональд Трамп олон зуун хүнсний бүтээгдэхүүний импортод ногдуулж байсан дэлхийн харилцан татварыг цуцалж байгаагаа мэдэгдлээ. Энэ нь түүний татвар нь инфляцыг өдөөдөггүй гэж удаан хугацаанд шаардаж ирсэн байр сууринаас эрс ухарсан алхам болж байна. Шийдвэр нь хүнсний үнийн өсөлтөөс үүдэлтэй олон нийтийн дарамт нэмэгдэж буй үед гарсан байна.\n\nТрампын засаг захиргаа татварыг цуцлах шийдвэрийг инфляцыг бууруулах зорилготой гэж тайлбарлаж байгаа бөгөөд энэ нь Ерөнхийлөгчийн худалдааны бодлогод томоохон өөрчлөлт оруулж байна. Өмнө нь Трамп татварыг Америкийн үйлдвэрлэлийг хамгаалах, төсвийн орлогыг нэмэгдүүлэх гол хэрэгсэл гэж тодорхойлж байсан юм. Гэсэн хэдий ч хүнсний бүтээгдэхүүний үнэ өссөөр байгаа нь засаг захиргааг бодлогоо эргэн харахад хүргэсэн байна.\n\nЭнэ шийдвэр нь Трампын улс төрийн байр сууринд ч өөрчлөлт оруулж байна. Ерөнхийлөгч өөрийн MAGA хөдөлгөөний гол холбоотон болох Бүгд найрамдах намын Төлөөлөгчдийн танхимын гишүүн Маржори Тейлор Гринийг дэмжихээ больсон тухайгаа мөн мэдэгдсэн байна. Энэ нь түүний улс төрийн эвсэлд хагарал үүсч буйг харуулж байна.\n\nХүнсний татварыг цуцлах нь хэрэглэгчдийн зардалд шууд нөлөөлөх төлөвтэй бөгөөд импортын хүнсний бүтээгдэхүүний үнэ буурах боломжтой гэж шинжээчид үзэж байна. Гэсэн хэдий ч энэ шийдвэр нь АНУ-ын худалдааны түншүүдтэй харилцаа, дотоодын үйлдвэрлэгчдийн өрсөлдөх чадварт хэрхэн нөлөөлөх нь цаашид анхаарал татаж байна.", textEn:"US President Donald Trump has announced that he is eliminating the global reciprocal tariffs on hundreds of food imports. The move is a dramatic reversal for a president who has long insisted that his import duties do not fuel inflation. The decision comes as public pressure grows over rising food prices.\n\nThe Trump administration presents the removal of the tariffs as aimed at bringing inflation down, marking a major change in the President's trade policy. Trump had previously described tariffs as a key tool to protect American industry and raise budget revenue. But continued rises in food prices have pushed the administration to reconsider its approach.\n\nThe decision also signals a shift in Trump's political standing. The President has also said he is no longer backing Marjorie Taylor Greene, a Republican congresswoman and a major ally of his MAGA movement. The move points to strains within his political coalition.\n\nScrapping the food tariffs is expected to affect consumer spending directly, and analysts say imported food prices could fall. However, attention will now turn to how the decision affects relations with US trading partners and the competitiveness of domestic producers."},
  {id:9, cat:"delhii", title:"АСЕАН-ы дээд хэмжээний уулзалт Филиппинд эхэлж, дэлхийн удирдагчид цугларч байна", titleEn:"ASEAN summit opens in the Philippines as world leaders gather", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline%20in%20Manila%2016.jpg?width=760", text:"Зүүн Өмнөд Азийн орнуудын холбоо буюу АСЕАН-ы дээд хэмжээний уулзалт Филиппинд арваннэгдүгээр сарын 16-17-нд болно. Дэлхийн удирдагчид уулзалтад оролцохоор арваннэгдүгээр сарын 15-нд Манилад цугларч эхэлсэн байна. Энэ удаагийн дээд хэмжээний уулзалт нь бүс нутгийн хамтын ажиллагаа, худалдаа, аюулгүй байдлын асуудлыг хэлэлцэх чухал талбар болж байна.\n\nЭнэтхэгийн Ерөнхий сайд Нарендра Моди арваннэгдүгээр сарын 16-17-нд болох АСЕАН-ы дээд хэмжээний уулзалтад оролцохоор төлөвлөж байна. Модигийн оролцоо нь Энэтхэг, Зүүн Өмнөд Азийн харилцааг бэхжүүлэхэд чухал ач холбогдолтой гэж үзэж байна. Уулзалтын үеэр бүс нутгийн худалдаа, хөрөнгө оруулалт, дижитал эдийн засаг болон далайн аюулгүй байдлын асуудлыг хэлэлцэх төлөвтэй байна.\n\nФилиппин улс энэ удаагийн дээд хэмжээний уулзалтыг зохион байгуулж байгаа бөгөөд Манила хотод аюулгүй байдлын арга хэмжээг чангатгажээ. Уулзалтад АСЕАН-ы гишүүн орнуудын удирдагчид болон түнш орнуудын төлөөлөгчид оролцоно. АСЕАН нь Зүүн Өмнөд Азийн 10 орныг нэгтгэсэн бүс нутгийн байгууллага бөгөөд дэлхийн эдийн засаг, улс төрд нөлөө нь өссөөр байна.\n\nДээд хэмжээний уулзалтын үр дүн нь бүс нутгийн худалдааны хэлэлцээр, цаг уурын өөрчлөлтийн эсрэг хамтын ажиллагаа болон Өмнөд Хятадын тэнгисийн маргааны асуудалд хэрхэн нөлөөлөх нь олон улсын анхаарлыг татаж байна.", textEn:"The summit of the Association of Southeast Asian Nations, ASEAN, will be held in the Philippines on November 16-17. World leaders began gathering in Manila on November 15 to take part. This year's summit is an important forum for discussing regional cooperation, trade and security.\n\nIndian Prime Minister Narendra Modi is scheduled to attend the ASEAN summit on November 16-17. Modi's participation is seen as important for strengthening ties between India and Southeast Asia. The summit is expected to discuss regional trade, investment, the digital economy and maritime security.\n\nThe Philippines is hosting this year's summit, and security measures have been tightened in Manila. Leaders of ASEAN member states and representatives of partner countries will attend. ASEAN brings together 10 Southeast Asian nations, and its influence in the global economy and politics continues to grow.\n\nThe outcome of the summit will be closely watched for its impact on regional trade agreements, joint action against climate change, and the South China Sea disputes."},
  {id:10, cat:"delhii", title:"Өмнөд Судан анхны үндэсний сонгуулиа 2027 оны хоёрдугаар сар хүртэл хойшлууллаа", titleEn:"South Sudan postpones first national elections until February 2027", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Juba%20City.jpg?width=760", text:"Өмнөд Судан улс анхны үндэсний сонгуулиа 2027 оны хоёрдугаар сар хүртэл хойшлуулсан байна. 2011 онд тусгаар тогтносон дэлхийн хамгийн залуу улс болох Өмнөд Судан анх удаа үндэсний хэмжээнд сонгууль явуулахаар төлөвлөж байсан ч сонгуулийн бэлтгэл хангалтгүй байгаа нь хойшлуулах шийдвэрийг хүргэсэн байна.\n\nСонгуулийг хойшлуулах шийдвэр нь тус улсын улс төрийн шилжилтийн үйл явцад дахин саатал үүсгэж байна. Өмнөд Судан 2013-2018 онд иргэний дайнд нэрвэгдэж, олон мянган хүн амиа алдаж, сая сая хүн дүрвэжээ. 2018 оны энхийн хэлэлцээрийн дараа шилжилтийн засгийн газар байгуулагдсан ч сонгууль явуулах хугацаа хэд хэдэн удаа хойшлогдсон байна.\n\nШинжээчид сонгуулийг хойшлуулах нь улс төрийн тогтвортой байдалд сөргөөр нөлөөлж болзошгүй гэж үзэж байна. Сонгуулийн бэлтгэлд сонгогчдын бүртгэл, сонгуулийн хууль, аюулгүй байдлын баталгаа зэрэг олон асуудал багтдаг бөгөөд эдгээрийг шийдвэрлэхэд нэмэлт хугацаа шаардлагатай байгаа аж. Олон улсын хамтын нийгэмлэг Өмнөд Суданы эрх баригчдыг сонгуулийг шударга, ил тод явуулахыг уриалж байна.\n\nӨмнөд Судан нь газрын тосны баялаг нөөцтэй ч ядуурал, хүмүүнлэгийн хямралтай тулгарч байна. Сонгууль нь тус улсад ардчилсан засаглалыг бэхжүүлэх, энх тайвныг тогтвортой болгох чухал алхам гэж үзэж байгаа тул хойшлуулсан нь олон улсын анхаарлыг татаж байна.", textEn:"South Sudan has postponed its first national elections until February 2027. The world's youngest country, which became independent in 2011, had planned to hold nationwide elections for the first time, but insufficient preparations led to the decision to delay them.\n\nThe postponement is another delay in the country's political transition. South Sudan suffered a civil war from 2013 to 2018, in which many thousands of people were killed and millions displaced. After the 2018 peace agreement, a transitional government was formed, but the date for elections has been postponed several times.\n\nAnalysts say the delay could harm political stability. Election preparations include voter registration, electoral laws and security guarantees, and more time is needed to resolve these issues. The international community is urging South Sudan's authorities to hold the elections fairly and transparently.\n\nSouth Sudan has rich oil reserves but faces poverty and a humanitarian crisis. Elections are seen as an important step towards strengthening democratic governance and stabilising peace, so the postponement has drawn international attention."},
  {id:11, cat:"delhii", title:"АНУ-д холбооны доголдлоос нислэгүүд зогсож, дөрвөн цагийн дараа сэргэв", titleEn:"US flights grounded by communications outage, resume after four hours", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Airplane%20at%20airport%20Chennai.jpg?width=760", text:"АНУ-ын Холбооны нисэхийн захиргаа буюу FAA арваннэгдүгээр сарын 13-ны баасан гарагт агаарын хөдөлгөөний удирдлагын системийг доголдуулсан харилцаа холбооны тасалдалаас болж улсын хэмжээнд нислэгийг дөрвөн цагаас илүү хугацаанд зогсоосон байна. Даллас-Форт Вортын олон улсын нисэх буудал зэрэг томоохон нисэх буудлуудад зорчигчид нислэгийн мэдээллийн дэлгэцийн өмнө хүлээж, нислэгүүд хойшилжээ.\n\nFAA нислэгийг сэргээсний дараа ч саатал үргэлжилсэн байна. Харилцаа холбооны тасалдал нь агаарын хөдөлгөөний удирдлагын системийг ажиллуулах боломжгүй болгосон бөгөөд аюулгүй байдлыг хангах үүднээс нислэгийг зогсоох шийдвэр гаргасан байна. Энэ нь сүүлийн жилүүдэд АНУ-д гарсан хамгийн томоохон нислэгийн зогсолтуудын нэг болж байна.\n\nЗорчигчид нисэх буудлуудад олон цагаар хүлээх шаардлагатай болж, агаарын тээврийн компаниуд нислэгийн хуваариа шинэчлэн зохион байгуулжээ. FAA тасалдлын шалтгааныг шалгаж байгаа бөгөөд системийн найдвартай байдлыг сайжруулах арга хэмжээ авах төлөвтэй байна.\n\nЭнэ үйл явдал нь АНУ-ын агаарын хөдөлгөөний удирдлагын системийн эмзэг байдлыг харуулж, дэд бүтцийг шинэчлэх шаардлагатайг онцолсон байна. Шинжээчид харилцаа холбооны системийн нөөц, сэлбэг шийдлийг бэхжүүлэх нь ийм тасалдлаас урьдчилан сэргийлэхэд чухал гэж үзэж байна.", textEn:"The US Federal Aviation Administration (FAA) grounded flights nationwide for more than four hours on Friday, November 13, after a telecommunications outage disrupted air traffic control systems. At major airports including Dallas Fort Worth International, travellers waited in front of flight information displays as flights were delayed.\n\nDelays continued even after the FAA allowed flights to resume. The communications outage made it impossible to operate air traffic control systems, and flights were stopped to ensure safety. It was one of the largest nationwide ground stops in the United States in recent years.\n\nPassengers had to wait for hours at airports, and airlines reorganised their flight schedules. The FAA is investigating the cause of the outage and is expected to take steps to improve the reliability of the system.\n\nThe incident highlighted the vulnerability of the US air traffic control system and the need to modernise its infrastructure. Experts say strengthening backup and redundancy in communications systems is important to prevent such outages."},
  {id:12, cat:"sport", title:"FIBA 3x3 Зайсан: Улаанбаатар баг шөвгийн наймд шалгарч, өнөөдөр аварга тодорно", titleEn:"FIBA 3x3 Zaisan: Ulaanbaatar reach quarter-finals as champion is crowned today", time:"30 мин", timeEn:"30 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/AG%2023%203x3%20Basketball%20110.jpg?width=760", text:"FIBA 3x3 Дэлхийн цуврал тэмцээний Зайсан дахь гараа өчигдөр буюу арваннэгдүгээр сарын 14-нд Улаанбаатар хотын Чингис хааны өргөн чөлөөнд байрлах “Крокус” арга хэмжээний танхимд эхэллээ. Энэ нь 2026 оны улиралд Монголд болж буй хоёр дахь гараа бөгөөд оны эхээр Улаанбаатарт болсон тэмцээний дараа болж байна. 16 баг аваргын төлөө өрсөлдөж байна.\n\nНээлтийн өдөр Сербийн Уб болон Нидерландын Амстердам RABOBANK багууд хэсгийн тоглолтуудад ялагдалгүй түрүүлж, шөвгийн наймд шалгарлаа. Хятадын Шанхай баг ч мөн хэсгээ ялагдалгүй тэргүүлжээ. Талбайн эзэн Монголын “Улаанбаатар MMC Energy” баг Лиман багт 21:18-аар хожигдож эхэлсэн ч Торонтог 20:15-аар хожиж, хэсгээсээ хоёрдугаар байраар шалгарч, хасагдах шатанд орсон байна.\n\nШөвгийн наймын тоглолтууд өнөөдөр буюу арваннэгдүгээр сарын 15-нд болно. Уб баг талбайн эзэн Улаанбаатар багтай, Шанхай Дэчинтэй, Амстердам RABOBANK Баскетс Боннтой, Лиман Цибнатай тус тус тоглоно. Анх удаа Зайсан дүүрэгт болж буй энэ тэмцээний аварга өнөөдөр тодорно.\n\nЗайсан нь Улаанбаатар хотын өмнөд хэсэгт орших алдартай толгод, орон сууц, худалдаа, зугаа цэнгэлийн дүүрэг бөгөөд 3x3 сагсан бөмбөгийн халуун цэгүүдийн нэг гэдгээрээ алдартай. Монголын хоёр баг болох “Улаанбаатар” болон “Сансар M Банк” энэ тэмцээнд оролцож, нутгийн хөгжөөн дэмжигчдийн дэмжлэгийг авч байна.", textEn:"The FIBA 3x3 World Tour stop in Zaisan began yesterday, November 14, at Crocus Events Hall on Chinggis Khan Avenue in Ulaanbaatar. It is the second Mongolian stop of the 2026 season, following the WT Ulaanbaatar event earlier this year. Sixteen teams are competing for the title.\n\nOn the opening day, Ub of Serbia and Amsterdam RABOBANK of the Netherlands went unbeaten in pool play to reach the quarter-finals. Shanghai of China also swept their pool. Home favourites Ulaanbaatar MMC Energy lost their opener 21-18 to Liman but responded by beating Toronto 20-15 to finish second in the pool and advance to the knockout stage.\n\nThe quarter-finals take place today, November 15. Ub face home favourites Ulaanbaatar MMC Energy, Shanghai meet DeQing, Amsterdam RABOBANK play Baskets Bonn, and Liman take on Cibona. The first-ever FIBA 3x3 World Tour Zaisan champion will be crowned today.\n\nZaisan is a famous hill and a vibrant residential, shopping and entertainment district in the southern part of Ulaanbaatar, known as one of the hotbeds of 3x3 basketball. Two Mongolian teams, Ulaanbaatar and Sansar M Bank, are competing in the tournament with the support of local fans."},
  {id:13, cat:"sport", title:"Энэтхэг Бутаныг 2:1-ээр хожиж, SAFF аваргын финалд шалгарлаа", titleEn:"India beat Bhutan 2-1 to reach SAFF Championship final", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Kashima%20Soccer%20Stadium%20Interior%20View.jpg?width=760", text:"Холбооны аварга Энэтхэг улс арваннэгдүгээр сарын 14-ний бямба гарагт Дакка хотын Үндэсний цэнгэлдэх хүрээлэнд болсон SAFF аваргын хагас шигшээд Бутаныг 2:1-ээр хожиж, финалд шалгарлаа. Энэтхэгийн П.В.Вишну найм дахь минутад, Чингленсана Сингх 27 дахь минутад гоол оруулж, багаа тэргүүлсэн байна. Бутаны Кинзанг Таши Тобден 48 дахь минутад нэг гоол эргүүлэн оруулсан ч Энэтхэг ялалтаа хадгалж чадсан байна.\n\nЭнэ тоглолт SAFF аваргын түүхэнд видео туслах шүүгчийн буюу VAR системийг анх удаа ашигласан тоглолт болсон нь онцлог байв. Тобдены гоолын үеэр VAR анхны офсайд шийдвэрийг хүчингүй болгож, гоолыг тоолсон байна. Тэмцээний түүхэнд VAR ашигласан анхны тохиолдол нь Өмнөд Азийн хөлбөмбөгийн хөгжилд чухал алхам боллоо.\n\nЭнэтхэг улс 23 хүртэлх насны нөөц бүрэлдэхүүнээрээ оролцож байгаа бөгөөд ахлах шигшээ баг нь Шинэ Зеланд улсад нөхөрсөг тоглолт хийж байгаа юм. Дарангуйлагч дасгалжуулагч Наушад Моосагийн удирдлага дор тоглож буй Энэтхэгийн залуус 14 дэх удаагаа SAFF аваргын финалд шалгарч, 2018 оны тэмцээнээс бусад бүх удаад финалд хүрсэн байна.\n\nФинал арваннэгдүгээр сарын 17-нд Дакка хотод болох бөгөөд Энэтхэг улс талбайн эзэн Бангладеш эсвэл Пакистаны ялагчтай тоглоно. Есөн удаагийн аварга Энэтхэг улс арав дахь цолоо авахын төлөө нэг хожил дутмаг байна.", textEn:"Defending champions India beat Bhutan 2-1 in the SAFF Championship semifinal at the National Stadium in Dhaka on Saturday, November 14, to reach the final. P.V. Vishnu opened the scoring in the eighth minute and Chinglensana Singh doubled India's lead in the 27th minute. Bhutan's Kinzang Tashi Tobden pulled one back in the 48th minute, but India held on for the win.\n\nThe match marked the historic debut of the Video Assistant Referee (VAR) system in the SAFF Championship. VAR overturned the initial offside call on Tobden's goal, allowing it to stand. The first use of the system in the tournament's history is an important step for South Asian football.\n\nIndia are fielding their U-23 reserve squad, as the senior team is currently playing friendly matches in New Zealand. Under head coach Naushad Moosa, the young Indian side have reached the SAFF Championship final for the 14th time, having reached the final in every edition except 2018.\n\nThe final will be played on November 17 in Dhaka, where India will face the winner of the second semifinal between hosts Bangladesh and Pakistan. Nine-time champions India are one win away from a record-extending 10th title."},
  {id:14, cat:"soyol", title:"Хүннүгийн 73 метрийн булшнаас Ромын шилэн эдлэл, алтан чимэглэл олдлоо", titleEn:"Roman glass and gold ornaments found in 73-metre Xiongnu tomb", time:"45 мин", timeEn:"45 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Warring%20States%20Xiongnu%20Gold%20Crown%20-%20b.jpg?width=760", text:"Монголын зүүн нутаг дахь Дуурлиг Нарс оршуулгын газарт байрлах Хүннүгийн эзэнт гүрний үеийн сүрлэг булшнаас Ромын шилэн эдлэл, хаш чулуу, Солонгосын чимэглэл болон онцгой алтан эдлэл олдсон тухай археологичид мэдээллээ. Уг булш нь 73 метр орчим урт бөгөөд эртний нүүдэлчид болон Ромын эзэнт гүрэн, Хятад, Солонгосын хойг хоорондын худалдаа, соёлын холбоог харуулсан олдворууд агуулсан байна.\n\nСудалгааг Солонгосын Үндэсний музей, Монголын Шинжлэх ухааны академи, Монголын Үндэсний музейн мэргэжилтнүүд хамтран хийсэн байна. Олдсон эд зүйлсийн дунд Ромын шилэн эдлэл, хаш, Солонгосын чимэглэл болон өвөрмөц алтан эдлэл багтсан бөгөөд эдгээр нь Евразийн өргөн уудам нутаг дахь холбоог харуулж байна.\n\nХүннүгийн эзэнт гүрэн нь МЭӨ III зуунаас МЭ I зуун хүртэл Төв Азийн тал нутагт оршин тогтнож, Торгоны замын худалдаанд чухал үүрэг гүйцэтгэж байсан юм. Дуурлиг Нарс оршуулгын газар нь Хүннүгийн язгууртнуудын оршуулгын газруудын нэг бөгөөд өмнө нь ч чухал олдворууд олдсон байна. Энэ удаагийн нээлт нь Хүннүгийн элитүүд холын худалдааны сүлжээнд хэрхэн холбогдож байсныг харуулж байна.\n\nОлдворуудыг цаашид судалж, хадгалж, олон нийтэд үзүүлэхээр төлөвлөж байна. Энэхүү нээлт нь Монголын эртний түүх, соёлын өвийг судлахад чухал хувь нэмэр оруулж, олон улсын эрдэмтдийн анхаарлыг татаж байна.", textEn:"Archaeologists have examined a monumental tomb of the Xiongnu Empire at the Duurlig Nars cemetery in eastern Mongolia and discovered artifacts indicating trade and cultural ties between the ancient nomads and the Roman Empire, China and the Korean Peninsula. The tomb is approximately 73 metres long and contained Roman glass, jade, a Korean ornament and a unique gold artifact.\n\nThe research was conducted by specialists from the National Museum of Korea, the Mongolian Academy of Sciences and the National Museum of Mongolia. The finds show connections across Eurasia and shed light on the far-reaching trade networks of the Xiongnu elite.\n\nThe Xiongnu Empire dominated the Central Asian steppe from the 3rd century BCE to the 1st century CE and played an important role in Silk Road trade. The Duurlig Nars cemetery is one of the burial grounds of Xiongnu nobility, where important finds have been made before. This latest discovery shows how the Xiongnu elite were connected to long-distance trade networks.\n\nThe artifacts will be further studied, preserved and presented to the public. The discovery is an important contribution to the study of Mongolia's ancient history and cultural heritage and has drawn the attention of international scholars."},
  {id:15, cat:"soyol", title:"IVE Melon Music Awards-т дебют дуунуудаа шинэчлэн дуулж, Billboard 200-д анх удаа орлоо", titleEn:"IVE to perform debut songs at Melon Music Awards after first Billboard 200 entry", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/IVE%20%28%EC%95%84%EC%9D%B4%EB%B8%8C%29%20performing%20at%20the%202023%20World%20Scout%20Jamboree%20K-POP%20Super%20Live%20Concert.jpg?width=760", text:"Солонгосын охидын хамтлаг IVE нь арваннэгдүгээр сарын 14-15-нд Сөүл хотын Гочеок Скай Домд болж буй Melon Music Awards 2026 шагнал гардуулах ёслолын хоёр дахь өдөр буюу өнөөдөр тусгай тоглолт хийнэ. Тус хамтлаг дебют үеийнхээ дуунуудыг шинэ найруулгаар дуулж, шүтэн бишрэгчдэдээ гэнэтийн бэлэг барих гэж байна. Яг ямар дуу дуулах нь нууц хэвээр байгаа бөгөөд сонирхлыг улам нэмэгдүүлж байна.\n\nMelon Music Awards нь Солонгосын хөгжмийн нэр хүндтэй шагналуудын нэг бөгөөд энэ жил анх удаа хоёр өдөр үргэлжилж байна. Эхний өдөрт aespa, NCT DREAM, RIIZE, ATEEZ зэрэг 14 хамтлаг оролцсон бол хоёр дахь өдөрт IVE, ILLIT, NCT 127, PLAVE зэрэг хамтлагууд оролцохоор төлөвлөжээ. Улаан хивсний ёслол Солонгосын цагаар 17:00 цагт, үндсэн ёслол 18:00 цагт эхэлнэ.\n\nЭнэхүү тусгай тоглолт нь IVE-ийн АНУ-ын чартад гаргасан шинэ амжилтын дараахан болж байна. Тус хамтлагийн хамгийн сүүлийн мини цомог “Looks Can Kill” нь аравдугаар сарын 26-нд гарсан бөгөөд арваннэгдүгээр сарын 14-ний чартаар АНУ-ын үндсэн цомгийн чарт болох Billboard 200-д анх удаа орсон байна. Энэ нь IVE-ийн карьер дахь Billboard 200-д орсон анхны тохиолдол юм.\n\nIVE нь 2021 оны сүүлээр дебют хийснээсээ хойш хурдан хугацаанд тэргүүлэх охидын хамтлагуудын нэг болсон юм. Тусгай тоглолтыг Melon апп болон Wavve платформоор шууд дамжуулан үзэх боломжтой.", textEn:"South Korean girl group IVE will perform a special stage on the second day of the Melon Music Awards 2026, held on November 14-15 at the Gocheok Sky Dome in Seoul. The group will perform songs from the early days of their career in new arrangements, offering a surprise for fans. Exactly which songs they will sing has been kept secret, adding to the anticipation.\n\nThe Melon Music Awards is one of South Korea's most prestigious music awards, and this year it runs over two days for the first time. The first day featured 14 acts including aespa, NCT DREAM, RIIZE and ATEEZ, while the second day will feature IVE, ILLIT, NCT 127 and PLAVE. The red carpet begins at 5 p.m. KST, followed by the main ceremony at 6 p.m.\n\nThe special performance comes shortly after IVE achieved a new milestone on the US charts. Their latest mini album, \"Looks Can Kill\", released on October 26, entered the Billboard 200, the main US album chart, on the chart dated November 14. It marks IVE's first-ever entry on the Billboard 200.\n\nIVE debuted in late 2021 and quickly became one of the leading girl groups. The special performance can be watched live via the Melon app and the Wavve platform."},
  {id:16, cat:"tech", title:"SpaceX Starship 15-р нислэгээ тойрог замд хүргэв — бустерээ барьж чадсангүй", titleEn:"SpaceX Starship reaches orbit on Flight 15 but booster catch fails", time:"30 мин", timeEn:"30 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/SpaceX%20Starship%20SN8%20launch%20as%20viewed%20from%20South%20Padre%20Island.jpg?width=760", text:"SpaceX компани арваннэгдүгээр сарын 13-ны баасан гарагт Техас мужийн Старбейс хотоос Starship хөлгийн 15 дахь туршилтын нислэгийг хийж, хөлгийг тойрог замд амжилттай хүргэлээ. 124 метр өндөр пуужин орон нутгийн цагаар 16:45 цагт хөөрсөн бөгөөд дээд шат нь тойрог замд гарч, 26 шинэ үеийн Starlink хиймэл дагуул амжилттай байрлуулсан байна. Энэ нь Starship-ийн 2023 оноос хойших 15 дахь туршилтын нислэг бөгөөд үйл ажиллагааны Starlink хиймэл дагуулыг тойрог замд хүргэсэн хоёр дахь нислэг юм.\n\nГэсэн хэдий ч нислэгийн хоёр шатлалыг хоёуланд нь буцаан авчрах төлөвлөгөө бүтэлгүйтлээ. Хөөрсний дараахан Super Heavy V3 бустерт гэмтэл гарч, автомат систем нь буцаан барих оролдлогыг цуцалж, бустерийг хөөргөх цамхагаас холдуулан Мексикийн булан руу чиглүүлсэн байна. Бустер далайд унахдаа дэлбэрч, галын бөмбөлөг үүсгэсэн байна. Энэ нь V3 Super Heavy бустерийг цамхагт буцаан барих анхны оролдлого байв.\n\nДээд шат буюу Ship нь тойрог замдаа үргэлжлэн нисч, дэлхийг 14 удаа тойроод, хөөрснөөсөө 22 цаг хагасын дараа Старбейс рүү буцаж, механик гар буюу “chopsticks”-ээр бариулахаар төлөвлөж байна. Буцах оролдлого нь арваннэгдүгээр сарын 14-ний орой буюу 15-ны өглөөний үүрээр товлогдсон бөгөөд амжилттай болбол тойрог замд гарсан Starship-ийн дээд шатлыг хөөргөх талбайд анх удаа буцаан авах үйл явдал болно.\n\nБүрэн дахин ашиглах боломжтой пуужин бүтээх нь SpaceX-ийн зорилтын гол цөм бөгөөд Starship-ийн ахиц нь НАСА-д ч чухал юм. НАСА нь Starship-ийг 2027 оны зун төлөвлөгдсөн Artemis III нислэг зэрэг сансрын нисгэгчдийг саран дээр буулгах сарны буултын хөлөг болгон хувиргахын тулд 3.2 тэрбум орчим ам.долларын санхүүжилт олгосон байна.", textEn:"SpaceX launched the 15th test flight of its Starship spacecraft from Starbase, Texas, on Friday, November 13, successfully reaching orbit. The 124-metre rocket lifted off at 4:45 p.m. local time, and the upper stage reached orbit and deployed 26 next-generation Starlink satellites. It was Starship's 15th test flight since 2023 and the second to deliver operational Starlink satellites to orbit.\n\nHowever, the plan to recover both stages of the rocket failed. Shortly after separation, the Super Heavy V3 booster suffered a malfunction, and an automatic abort diverted it away from the launch tower towards the Gulf of Mexico instead of a planned catch. The booster burst into flames as it came down into the sea. It was the first attempt to catch a V3 Super Heavy booster at the tower.\n\nThe upper stage, called Ship, continued into orbit and is expected to complete 14 orbits before returning to Starbase about 22 and a half hours after liftoff, to be caught by the giant mechanical arms known as chopsticks. The return attempt is targeted for the evening of November 14, and if successful it would mark the first recovery of an orbital Starship upper stage at the launch site.\n\nA fully reusable rocket is central to SpaceX's plans to cut launch costs, and Starship's progress also matters for NASA. NASA has provided around 3.2 billion dollars to turn the Ship into a lunar lander for crewed Moon missions, including Artemis III, planned for the summer of 2027."},
  {id:17, cat:"tech", title:"CISA: Хакерууд WordPress-ийн 18 жилийн настай сул талыг ашиглаж байна", titleEn:"CISA: Hackers exploiting 18-year-old WordPress core flaw", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/BalticServers%20data%20center.jpg?width=760", text:"АНУ-ын Кибер аюулгүй байдал, дэд бүтцийн аюулгүй байдлын агентлаг буюу CISA хакерууд WordPress-ийн үндсэн систем дэх 18 жилийн настай сул талыг идэвхтэй ашиглаж байгаа талаар анхаарууллаа. Энэхүү сул тал нь дэлхий даяар сая сая вэбсайтыг ажиллуулдаг түгээмэл агуулгын удирдлагын системд нөлөөлж байгаа бөгөөд халдлага үйлдэгчид үүнийг ашиглан вэбсайтуудад нэвтэрч байна.\n\nCISA-ийн анхааруулга нь байгууллагууд болон вэбсайт эзэмшигчдэд системийг яаралтай шинэчлэн, аюулгүй байдлын засварыг хэрэгжүүлэхийг уриалж байна. 18 жилийн турш оршин байсан сул талыг ашиглах нь кибер халдлагын аюул нь шинэ сул талаас гадна хуучин, мэдэгдэж байсан асуудлуудаас ч үүдэлтэй болохыг харуулж байна. Олон вэбсайт хуучирсан хувилбаруудыг ашиглаж байгаа нь эрсдэлийг улам нэмэгдүүлж байна.\n\nWordPress нь дэлхийн вэбсайтуудын ихээхэн хувийг ажиллуулдаг бөгөөд ийм өргөн хэрэглээ нь түүнийг халдлага үйлдэгчдийн байнгын бай болгодог. Мэргэжилтнүүд вэбсайт эзэмшигчдэд системээ тогтмол шинэчлэх, хүчтэй нууц үг ашиглах, хоёр хүчин зүйлийн баталгаажуулалтыг идэвхжүүлэх, сэжигтэй үйл ажиллагааг хянахыг зөвлөж байна. CISA-ийн анхааруулга нь кибер аюулгүй байдлын үндсэн арга хэмжээг дагаж мөрдөх нь чухал гэдгийг дахин сануулж байна.", textEn:"The US Cybersecurity and Infrastructure Security Agency (CISA) has warned that hackers are actively exploiting an 18-year-old vulnerability in the WordPress core. The flaw affects the widely used content management system that powers millions of websites around the world, and attackers are using it to gain access to websites.\n\nCISA's warning urges organisations and website owners to update their systems urgently and apply security patches. The exploitation of a flaw that has existed for 18 years shows that cyber threats come not only from new vulnerabilities but also from old, known issues. Many websites run outdated versions, which increases the risk.\n\nWordPress powers a large share of the world's websites, and this wide use makes it a constant target for attackers. Experts advise website owners to update their systems regularly, use strong passwords, enable two-factor authentication and monitor for suspicious activity. CISA's warning is a reminder of the importance of following basic cybersecurity practices."},
  {id:18, cat:"oron-nutag", title:"ХӨВСГӨЛ: Хилэнтийн гүүрээс Мөрөн чиглэлийн хатуу хучилттай зам бүрэн дууслаа", titleEn:"KHUVSGUL: Paved road from Khilentiin Bridge to Murun fully completed", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/202408%20View%20from%20car%20on%20the%20way%20from%20Ulaanbaatar%20to%20Kharkhorin%2C%20Mongolia%2061.jpg?width=760", text:"Хөвсгөл аймгийн замын сангийн хөрөнгө оруулалтаар Хилэнтийн гүүрээс Мөрөн чиглэлийн хатуу хучилттай авто замын ажил бүрэн дууслаа. Энэ тухай МОНЦАМЭ агентлаг арваннэгдүгээр сарын 12-нд мэдээлсэн байна. Тус ажлын гүйцэтгэгчээр “Хүслэнт бүтээмж” ХХК шалгарч, хугацаанд нь хийж гүйцэтгэсэн байна.\n\nМөрөн суманд 2025-2026 онд орон нутгийн хөрөнгө оруулалтаар нийт 14.1 км авто замын бүтээн байгуулалтын ажил үргэлжилж, төвийн дөрвөн замын уулзварыг өргөтгөх бүтээн байгуулалтын ажлыг мөн “Хүслэнт бүтээмж” ХХК хийж гүйцэтгэсэн байна. Мөн 35 кВ-ын дэд станц барих, Мөрөн сумын дөрвөн замын уулзварыг өргөтгөх зэрэг ажлуудыг хийж, Мөрөн сумын Хилэнтийн гүүр хүртэлх авто замыг хатуу хучилттай болголоо.\n\nХөвсгөл аймаг энэ оныг “Амьдрах орчноо сайжруулж, өрхийн үйлдвэрлэлийг дэмжих” жил болгон зарлаж, 64 тэрбум төгрөгийн бүтээн байгуулалтын ажлыг хэрэгжүүлж байна. Тус аймаг 2024-2028 оны хооронд 208 тэрбум төгрөгийн хөрөнгө оруулалтын ажил хийх бөгөөд энэ дөрвөн жилийн хугацаанд нийт 25 км авто зам барихаар төлөвлөжээ.\n\nШинэ зам нь Мөрөн хотын иргэдийн зорчих нөхцөлийг сайжруулж, Хөвсгөл нуур руу чиглэсэн аялал жуулчлалын урсгалыг дэмжих юм. Хөвсгөл аймагт жил бүр 150,000 орчим дотоод, гадаадын жуулчин ирдэг бөгөөд замын дэд бүтэц сайжрах нь орон нутгийн эдийн засагт чухал нөлөө үзүүлнэ.", textEn:"Construction of the paved road from Khilentiin Bridge towards Murun has been fully completed with investment from the Khuvsgul aimag road fund, MONTSAME reported on November 12. The contractor, \"Khuslent Buteemj\" LLC, was selected for the work and completed it on schedule.\n\nIn Murun soum, a total of 14.1 km of roads were built with local investment in 2025-2026, and the same company expanded the central four-way intersection. A 35 kV substation was also built, and the road from Murun to Khilentiin Bridge was paved.\n\nKhuvsgul aimag has declared this year the year of \"Improving the living environment and supporting household production\" and is implementing 64 billion tugriks of construction work. Between 2024 and 2028, the aimag will carry out 208 billion tugriks of investment, including 25 km of roads.\n\nThe new road will improve travel conditions for residents of Murun town and support tourist flows towards Lake Khuvsgul. Around 150,000 domestic and foreign tourists visit Khuvsgul aimag each year, and better road infrastructure will have an important effect on the local economy.", region:"khuvsgul"},
];

function aTitle(a){ return LANG === "en" ? (a.titleEn || a.title) : a.title; }
function aTime(a){ return LANG === "en" ? (a.timeEn || a.time) : a.time; }
function aText(a){ if(a.text) return LANG === "en" ? (a.textEn || a.text) : a.text; return SAMPLE_TEXT[LANG][a.id === 1 ? "long" : "short"]; }
function aRegion(a){ return a.region ? ((REGIONS[LANG] && REGIONS[LANG][a.region]) || a.region) : ""; }

// ===== Ханш · Цаг агаар (өдөр бүр шинэчлэгдэнэ; цаг агаарыг Open-Meteo-гоос шууд татна) =====
const RATES = {date:"2026-11-15", items:[
  {code:"USD", mnt:3603.46, chg:0}, {code:"EUR", mnt:3985.43, chg:0}, {code:"JPY", mnt:22.54, chg:0},
  {code:"CNY", mnt:540.2, chg:0}, {code:"KRW", mnt:2.69, chg:0}, {code:"RUB", mnt:43.79, chg:0}, {code:"GBP", mnt:4767.2, chg:0}
]};
let WEATHER = [
  {city:"Улаанбаатар", cityEn:"Ulaanbaatar", lat:47.9212, lon:106.9186, tz:"Asia/Ulaanbaatar", temp:-15, code:45},
  {city:"Токио", cityEn:"Tokyo", lat:35.6762, lon:139.6503, tz:"Asia/Tokyo", temp:11, code:2},
  {city:"Сөүл", cityEn:"Seoul", lat:37.5665, lon:126.978, tz:"Asia/Seoul", temp:10, code:2},
  {city:"Бээжин", cityEn:"Beijing", lat:39.9042, lon:116.4074, tz:"Asia/Shanghai", temp:4, code:2},
  {city:"Москва", cityEn:"Moscow", lat:55.7558, lon:37.6173, tz:"Europe/Moscow", temp:3, code:3}
];
function wIcon(code){
  if(code === 0) return "☀️";
  if(code === 1) return "🌤️";
  if(code === 2) return "⛅";
  if(code === 3) return "☁️";
  if(code === 45 || code === 48) return "🌫️";
  if(code === 51 || code === 53 || code === 55 || code === 80) return "🌦️";
  if(code === 56 || code === 57 || code === 61 || code === 63 || code === 65 || code === 66 || code === 67 || code === 81 || code === 82) return "🌧️";
  if(code === 71 || code === 73 || code === 75 || code === 77 || code === 85 || code === 86) return "❄️";
  if(code >= 95) return "⛈️";
  return "🌡️";
}
function fmtRate(v){
  if(v >= 100) return Math.round(v).toLocaleString("en-US");
  return v.toFixed(2);
}
function renderData(){
  const parts = [];
  RATES.items.forEach(r=>{
    let arrow = "";
    if(r.chg > 0) arrow = ' <span class="up">▲</span>';
    else if(r.chg < 0) arrow = ' <span class="down">▼</span>';
    parts.push(`<span class="tk"><b>${r.code}</b> ${fmtRate(r.mnt)}₮${arrow}</span>`);
  });
  WEATHER.forEach(w=>{
    const name = LANG === "en" ? w.cityEn : w.city;
    const t = w.temp > 0 ? "+" + w.temp : "" + w.temp;
    parts.push(`<span class="tk">${wIcon(w.code)} ${name} ${t}°C</span>`);
  });
  const html = parts.join('<span style="color:#666">•</span>');
  const track = document.getElementById("tickerTrack");
  if(track) track.innerHTML = html + '<span style="color:#666">•</span>' + html + '<span style="color:#666">•</span>';
  const usd = RATES.items.find(r=>r.code === "USD");
  const ue = document.getElementById("usdText");
  if(ue && usd) ue.textContent = "USD: " + fmtRate(usd.mnt) + "₮";
  const wt = document.getElementById("weatherText");
  const ub = WEATHER[0];
  if(wt && ub) wt.textContent = wIcon(ub.code) + " " + (LANG === "en" ? ub.cityEn : ub.city) + " " + (ub.temp > 0 ? "+" + ub.temp : ub.temp) + "°C";
}
function refreshWeather(){
  WEATHER.forEach((w, idx)=>{
    const url = "https://api.open-meteo.com/v1/forecast?latitude=" + w.lat + "&longitude=" + w.lon + "&current=temperature_2m%2Cweather_code&timezone=" + encodeURIComponent(w.tz);
    fetch(url).then(r=>r.json()).then(d=>{
      if(d && d.current){ WEATHER[idx].temp = Math.round(d.current.temperature_2m); WEATHER[idx].code = d.current.weather_code; renderData(); }
    }).catch(()=>{});
  });
}

